    status, result = handle_get_user_by_email(params)
    assert status == 200
    assert result == {"id": 1, "name": "Ada", "email": "ada@example.com"}

def test_handle_get_user_by_email_not_found():
    params = {"email": "nonexistent@example.com"}
    status, result = handle_get_user_by_email(params)
    assert status == 404
    assert result == {"error": "not found"}

def test_handle_get_user_by_email_invalid_missing():
    params = {}
    status, result = handle_get_user_by_email(params)
    assert status == 400
    assert result == {"error": "invalid email"}

